#include "unity.h"
#include "logic.h"

void setUp(void) {}
void tearDown(void) {}

void test_when_converting_zero_raw_adc_should_return_zero_celsius(void) {
    TEST_ASSERT_EQUAL_FLOAT(0.0, convert_to_celsius(0));
}

void test_when_converting_negative_raw_adc_should_return_error_code(void) {
    TEST_ASSERT_EQUAL_FLOAT(-999.0, convert_to_celsius(-10));
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(test_when_converting_zero_raw_adc_should_return_zero_celsius);
    RUN_TEST(test_when_converting_negative_raw_adc_should_return_error_code);
    return UNITY_END();
}

float convert_to_celsius(int raw_adc) {
    if (raw_adc < 0) {
        return -999.0f;                        // egen felkod
    }
    return raw_adc * (3.3f / 4095.0f) * 100.0f;  // 12-bitars ADC, 3,3 V, 10 mV/°C
}

