    TEST_ASSERT_EQUAL(expected, result);
}

// sensor_interface.h
typedef struct {
    int (*read_raw)(void);          // funktionspekare: riktig drivrutin eller mock
} sensor_hal_t;

float get_temperature(const sensor_hal_t *hal) {
    return convert_to_celsius(hal->read_raw());
}

// test_sensor_interface.c
static int mock_read_250(void) { return 250; }

void test_get_temperature_should_return_20point15(void) {
    sensor_hal_t mock_hal = { .read_raw = mock_read_250 };
    TEST_ASSERT_FLOAT_WITHIN(0.001f, 20.15f, get_temperature(&mock_hal));
}

